// パネル開閉の状態保持（中タブ全体で1つ）
window.cdsInfoOpen = false;
window.cdsToggleInfoPanel = function() {
  var panel = document.getElementById('cds-info-panel');
  if (!panel) return;
  window.cdsInfoOpen = !window.cdsInfoOpen;
  panel.classList.toggle('is-open', window.cdsInfoOpen);
};

// 記事1件分のHTMLを組み立て
function cdsBuildArticle(art) {
  if (!art) return '';

  // 出典記事（タイトル・日付・リンク）
  var esc = function(s){ return String(s == null ? '' : s).replace(/[&<>"]/g, function(c){ return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]; }); };
  var src = art.title ? ('<div class="cds-info-src" style="font-size:11.5px;color:#64748b;margin:2px 0 8px">📰 '
    + (window.cdsUsableUrl && window.cdsUsableUrl(art.url) ? '<a href="' + esc(art.url) + '" target="_blank" rel="noopener" style="color:#2563eb">' + esc(art.title) + '</a>' : esc(art.title))
    + (art.date ? '（' + esc(art.date) + '）' : '') + '</div>') : '';

  var hi = '';
  if (art.highlights && art.highlights.length) {
    hi = '<details class="cds-info-section" open><summary>📍 ハイライト</summary>'
       + '<div class="cds-info-section-body"><ul>'
       + art.highlights.map(function(h){ return '<li>' + h + '</li>'; }).join('')
       + '</ul></div></details>';
  }

  var sec = '';
  if (art.sections && art.sections.length) {
    sec = '<details class="cds-info-section"><summary>📝 章別サマリー</summary>'
        + '<div class="cds-info-section-body">'
        + art.sections.map(function(s){
            return '<h4>' + s.heading + '</h4>' + s.body;
          }).join('')
        + '</div></details>';
  }

  var raw = '';

  return '<div class="cds-info-article">' + src + hi + sec + raw + '</div>';
}

// ペインに対応する記事の出典URL（解説パネルと同じ対応表から引く）
window.cdsSourceForPane = function(paneId) {
  var map = window.INFO_PANE_MAP || {};
  var key = paneId ? map[paneId] : null;
  if (!key) return null;
  var k = Array.isArray(key) ? key[0] : key;
  var art = (window.INFO_REGISTRY || {})[k];
  return art && window.cdsUsableUrl(art.url) ? art.url : null;
};
// 記事IDまで入ったURLか（'https://mp.weixin.qq.com/s/' のような書きかけは使わない）
window.cdsUsableUrl = function(u) {
  return !!u && /^https?:\/\/[^\/]+\/.+/.test(u) && !/^https?:\/\/[^\/]+\/s\/?$/.test(u);
};
// 出典リンクを書き換える（URLが無ければ表示中の中タブの既定URL）
window.cdsSetSourceLink = function(url) {
  var a = document.getElementById('cds-source-link');
  if (!a) return;
  var u = url || ((window.CDS_SOURCE_URLS || {})[window.CDS_CURRENT_MID_TAB]) || '';
  if (!u) return;
  a.href = u; a.textContent = u;
};

// 指定ペインIDに対応する解説パネルを描画
window.cdsRenderInfoPanel = function(paneId) {
  var panel = document.getElementById('cds-info-panel');
  var meta = document.getElementById('cds-info-meta');
  var body = document.getElementById('cds-info-body');
  if (!panel || !body) return;

  // 出典リンクを表示中のペインの記事に合わせる（対応が無いペインは中タブの既定URL）
  try { window.cdsSetSourceLink(window.cdsSourceForPane(paneId)); } catch(e) {}

  var key = window.INFO_PANE_MAP[paneId];
  if (!key) {
    panel.style.display = 'none';
    return;
  }

  // 配列でも単一でも対応
  var keys = Array.isArray(key) ? key : [key];
  var arts = keys.map(function(k){ return window.INFO_REGISTRY[k]; }).filter(Boolean);
  if (!arts.length) {
    panel.style.display = 'none';
    return;
  }

  panel.style.display = 'block';
  var first = arts[0];
  if (meta) {
    meta.textContent = '';
  }
  body.innerHTML = arts.map(cdsBuildArticle).join('');

  // 開閉状態を維持
  panel.classList.toggle('is-open', !!window.cdsInfoOpen);
};
